-- P3: Daraja C2B v1 confirmations on some shortcodes carry SHA-256(MSISDN) instead of the number.
-- The hash of the canonical 2547... form (E.164 without '+') is kept beside the phone, generated by
-- PostgreSQL so it can never disagree with it. Every function used is immutable.

ALTER TABLE customers_customer
    ADD COLUMN phone_sha256 text GENERATED ALWAYS AS (encode(sha256(decode(substr(phone, 2), 'escape')), 'hex')) STORED;

CREATE INDEX customers_customer_tenant_phone_sha256_ix ON customers_customer (tenant_id, phone_sha256);
